import{_ as r,o,c as i,a3 as s,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/import-export-statistik/verwaltung-export-logineo-lms-csv.png",m=JSON.parse('{"title":"Daten für LOGINEO NRW LMS als CSV exportieren","description":"","frontmatter":{"title":"Daten für LOGINEO NRW LMS als CSV exportieren","source_pageid":1177,"source_revision":3964},"headers":[],"relativePath":"schild3/import-export-statistik/export-fuer-logineo-lms-csv-verwaltung-export.md","filePath":"schild3/import-export-statistik/export-fuer-logineo-lms-csv-verwaltung-export.md"}'),l={name:"schild3/import-export-statistik/export-fuer-logineo-lms-csv-verwaltung-export.md"};function p(u,n,d,c,g,h){return o(),i("div",null,[...n[0]||(n[0]=[s('<h1 id="daten-fur-logineo-nrw-lms-als-csv-exportieren" tabindex="-1">Daten für LOGINEO NRW LMS als CSV exportieren <a class="header-anchor" href="#daten-fur-logineo-nrw-lms-als-csv-exportieren" aria-label="Permalink to &quot;Daten für LOGINEO NRW LMS als CSV exportieren&quot;">​</a></h1><p>Wählen Sie Schülergruppe, Lernplattform und Exportumfang für LOGINEO NRW LMS. Dieser CSV-Export unterscheidet sich vom XML-Verfahren für LOGINEO NRW.</p><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-lms-csv.png"><img src="'+a+'" alt="Export der Daten von SchILD-NRW nach Logineo LMS als .csv-Datei. Das orange Auswahlfenster ist mit einem Klick auf die rechte Maustaste zu öffnen." loading="lazy"></a></p><p><em>Export der Daten von SchILD-NRW nach Logineo LMS als .csv-Datei. Das orange Auswahlfenster ist mit einem Klick auf die <code>rechte Maustaste</code> zu öffnen.</em></p><p>Öffnen Sie <strong>Verwaltung → Export → Logineo LMS (CSV)</strong>, um Daten für LOGINEO NRW LMS bereitzustellen. <strong>CSV</strong> bezeichnet eine Textdatei, in der Trennzeichen die Daten in Spalten gliedern.</p><p>Wählen Sie über <strong>Status</strong> und <strong>Klassen</strong> die Schülermenge aus, die exportiert werden soll.</p><p><strong>Exportumfang und Gruppen festlegen</strong></p><p>Wählen Sie oben rechts die <strong>Lernplattform</strong> aus. Diese muss zuvor unter <strong>Kataloge → Lernplattform</strong> eingerichtet worden sein. Auf der rechten Seite legen Sie die weiteren Exportdetails fest.</p><p>Wählen Sie die Daten und vor allem die Gruppen, wie es an der Schule geplant ist.</p><p>Abschließend ist festzulegen, ob die <strong>Schüler-</strong> und/oder die <strong>Lehrerdaten</strong> exportiert werden sollen und ob für die Nutzer <strong>Initialkennworte erzeugt</strong> und dann <strong>ausgegeben</strong> werden.</p><p>Konsultieren Sie hierzu bitte auch die Dokumentation von Logineo LMS.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis")]),e("p",null,[t("Beachten Sie den Unterschied von "),e("em",null,"Logineo NRW LMS"),t(" und "),e("em",null,"Logineo NRW"),t(". Diese Angebote lesen jeweils unterschiedliche Exportdaten von SchILD-NRW ein.")])],-1),e("p",null,"Konsultieren Sie zum Import die Dokumentation von Logineo LMS.",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Export_f%C3%BCr_Logineo_LMS_(CSV)_(Verwaltung_Export)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),t(" · Quellrevision 3964.")],-1)])])}const S=r(l,[["render",p]]);export{m as __pageData,S as default};
